#import "TFAIBuildCheckpoint.h"
#import "TFAIAgentContext.h"
#import <CommonCrypto/CommonDigest.h>
static NSString *DigestFile(NSString *path){NSInputStream *stream=[NSInputStream inputStreamWithFileAtPath:path];[stream open];CC_SHA256_CTX ctx;CC_SHA256_Init(&ctx);uint8_t buffer[65536];NSInteger count;while((count=[stream read:buffer maxLength:sizeof(buffer)])>0)CC_SHA256_Update(&ctx,buffer,(CC_LONG)count);[stream close];if(count<0)return nil;uint8_t digest[32];CC_SHA256_Final(digest,&ctx);NSMutableString *s=[NSMutableString new];for(NSUInteger i=0;i<32;i++)[s appendFormat:@"%02x",digest[i]];return s;}
NSString *TFAIBuildInputFingerprint(NSString *root,NSDictionary *config){NSMutableArray *files=[NSMutableArray new];NSDirectoryEnumerator *en=[NSFileManager.defaultManager enumeratorAtPath:root];for(NSString *relative in en){if([relative isEqual:@".git"]||[relative hasPrefix:@".git/"]){[en skipDescendants];continue;}NSString *path=[root stringByAppendingPathComponent:relative];NSDictionary *a=[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil];if([a[NSFileType] isEqual:NSFileTypeSymbolicLink])return nil;if(![a[NSFileType] isEqual:NSFileTypeRegular])continue;NSString *digest=DigestFile(path);if(!digest)return nil;[files addObject:@{@"path":relative,@"sha256":digest}];}files=[[files sortedArrayUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [a[@"path"] compare:b[@"path"]];}] mutableCopy];NSMutableArray *bundle=[NSMutableArray new];for(NSString *file in @[@"SDKResource.plist",@"SDK26Resource.plist"]){NSString *digest=DigestFile([NSBundle.mainBundle.bundlePath stringByAppendingPathComponent:file]);[bundle addObject:digest?:@"unavailable"];}NSDictionary *v=@{@"inputs":files,@"configuration":config,@"sdks":bundle,@"appBuild":[NSBundle.mainBundle objectForInfoDictionaryKey:@"CFBundleVersion"]?:@"test"};NSData *data=[NSJSONSerialization dataWithJSONObject:v options:NSJSONWritingSortedKeys error:nil];return data?[TFAIAgentContext fingerprint:[[NSString alloc]initWithData:data encoding:NSUTF8StringEncoding]]:nil;}
static void TrimCache(NSString *cache){NSArray *paths=[NSFileManager.defaultManager contentsOfDirectoryAtPath:cache error:nil];unsigned long long bytes=0;NSMutableArray *objects=[NSMutableArray new];for(NSString *name in paths)if([name.pathExtension isEqual:@"o"]){NSString *path=[cache stringByAppendingPathComponent:name];NSDictionary *attr=[NSFileManager.defaultManager attributesOfItemAtPath:path error:nil];bytes+=[attr[NSFileSize] unsignedLongLongValue];[objects addObject:@{@"path":path,@"bytes":attr[NSFileSize]?:@0,@"date":attr[NSFileModificationDate]?:NSDate.distantPast}];}[objects sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [a[@"date"] compare:b[@"date"]];}];for(NSDictionary *entry in objects){if(bytes<=256ULL*1024*1024&&objects.count<=512)break;NSString *path=entry[@"path"];if([NSFileManager.defaultManager removeItemAtPath:path error:nil]){bytes-=[entry[@"bytes"] unsignedLongLongValue];[NSFileManager.defaultManager removeItemAtPath:[path.stringByDeletingPathExtension stringByAppendingPathExtension:@"sha256"] error:nil];}if(bytes<=192ULL*1024*1024)break;}}
static NSString *Key(NSString *fingerprint,NSArray *arguments,NSString *root,NSString *build){if(!fingerprint.length)return nil;NSMutableArray *normalized=[NSMutableArray new];for(NSString *arg in arguments)[normalized addObject:[[arg stringByReplacingOccurrencesOfString:root withString:@"$PROJECT"] stringByReplacingOccurrencesOfString:build withString:@"$BUILD"]];return [TFAIAgentContext fingerprint:[NSString stringWithFormat:@"%@\n%@",fingerprint,normalized]];}
BOOL TFAIBuildRestoreObject(NSString *fingerprint,NSArray *arguments,NSString *root,NSString *build,NSString *object,NSString *cache){NSString *key=Key(fingerprint,arguments,root,build);if(!key)return NO;NSString *source=[cache stringByAppendingPathComponent:[key stringByAppendingString:@".o"]],*stamp=[cache stringByAppendingPathComponent:[key stringByAppendingString:@".sha256"]];NSString *expected=[NSString stringWithContentsOfFile:stamp encoding:NSUTF8StringEncoding error:nil];if(!expected.length||![DigestFile(source) isEqual:expected])return NO;return [NSFileManager.defaultManager copyItemAtPath:source toPath:object error:nil];}
void TFAIBuildSaveObject(NSString *fingerprint,NSArray *arguments,NSString *root,NSString *build,NSString *object,NSString *cache){NSString *key=Key(fingerprint,arguments,root,build),*digest=DigestFile(object);if(!key||!digest)return;[NSFileManager.defaultManager createDirectoryAtPath:cache withIntermediateDirectories:YES attributes:nil error:nil];NSString *path=[cache stringByAppendingPathComponent:[key stringByAppendingString:@".o"]];if(![NSFileManager.defaultManager fileExistsAtPath:path]){if(![NSFileManager.defaultManager copyItemAtPath:object toPath:path error:nil])return;[digest writeToFile:[cache stringByAppendingPathComponent:[key stringByAppendingString:@".sha256"]] atomically:YES encoding:NSUTF8StringEncoding error:nil];TrimCache(cache);}}
